void mainImage(out vec4 couleurSortie, vec2 coordPixel) {
    vec2 resolution = iResolution.xy;
    vec3 couleurAccumulee = vec3(0.0);
    float tempsAnime = iTime * 0.156;
    mat2 matriceRotationConstante = mat2(cos(mod(tempsAnime * 0.3, 14e-5) + vec4(0, 11, 33, 0)));

    vec2 coordNormalisees = (coordPixel + coordPixel - resolution) / resolution.y;

    float zoomCinementique = 1.2 + sin(iTime * 1.2) * 0.6;
    float distanceFocale = 1.716 * zoomCinementique;

    float amplitudeTorsion = sin(iTime * 1.5) * 0.8;

    for (int echantillonX = 0; echantillonX < 2; echantillonX++) {
        for (int echantillonY = 0; echantillonY < 2; echantillonY++) {
            vec2 decalageAA = (vec2(float(echantillonX), float(echantillonY)) - 0.5) * 0.5;
            vec2 positionSousPixel = (((coordPixel + decalageAA) * 2.0 - resolution) / resolution.y) / zoomCinementique;

            float angleTorsion = positionSousPixel.y * amplitudeTorsion;
            float cosAngle = cos(angleTorsion);
            float sinAngle = sin(angleTorsion);
            positionSousPixel = mat2(cosAngle, -sinAngle, sinAngle, cosAngle) * positionSousPixel;

            vec3 directionRayon = normalize(vec3(positionSousPixel, distanceFocale));

            vec3 couleurSousEchantillon = vec3(0.0);
            float densiteAccumulee = 0.0;
            float derniereDistance = 1.0;

            for (float pas = 1.0, distanceProfondeur = 1.0, distanceSurface, poidsLumiere, echelleGlobale, etapePliage, facteurInversion; pas++ < 110.0 && densiteAccumulee < 12.0; distanceProfondeur += distanceSurface * 0.55 + 0.0012) {
                derniereDistance = distanceProfondeur;
                vec3 positionEspace = directionRayon * distanceProfondeur;

                float rayonRayon = length(positionEspace.xy);
                float anglePolar = atan(positionEspace.y, positionEspace.x);
                float axeProfondeur = positionEspace.z - tempsAnime * 3.0;
                float coordonneeTordue = rayonRayon * 2.0 - axeProfondeur * 0.8;

                positionEspace.xy = mat2(cos(coordonneeTordue), sin(coordonneeTordue), -sin(coordonneeTordue), cos(coordonneeTordue)) * vec2(log(rayonRayon + 0.001) - tempsAnime * 0.5, cos(anglePolar * 2.0));
                positionEspace.z = abs(mod(axeProfondeur - 3.0, 6.0) - 3.0);
                positionEspace = abs(fract(positionEspace) - 0.778);

                for (echelleGlobale = 2.0, etapePliage = 0.0; etapePliage++ < 5.0; positionEspace = positionEspace * facteurInversion - vec3(0.7, 0.5, 0.8), echelleGlobale *= facteurInversion) {
                    positionEspace = 1.3635 - abs(positionEspace - 0.0024);
                    positionEspace.xy *= matriceRotationConstante;
                    facteurInversion = 1.35 / clamp(dot(positionEspace, positionEspace), 0.12, 1.0);
                }

                distanceSurface = abs(length(max(abs(positionEspace) - vec3(0.3, 0.6, 0.3), 313e-6)) - 0.0024) / echelleGlobale;

                float approximationNormale = abs(dot(positionEspace, directionRayon));
                poidsLumiere = 0.00035 / (distanceSurface * distanceSurface * 1.8 + 0.002) * (0.4 + 0.6 * approximationNormale);

                densiteAccumulee += poidsLumiere;

                vec3 couleurBase = 0.5 + 0.5 * cos(vec3(4.5, 1.2, 0.1) + coordonneeTordue * 1.5 + anglePolar * 2.0 + axeProfondeur * 0.5);
                vec3 couleurSombre = mix(vec3(0.001, 0.002, 0.005), couleurBase * 0.25, smoothstep(0.01, 0.3, poidsLumiere));

                float intensiteBord = smoothstep(0.005, 0.0, distanceSurface) * 1.2;
                vec3 couleurBord = vec3(0.05, 0.25, 0.6) * intensiteBord;

                couleurSousEchantillon += (couleurSombre + couleurBord) * poidsLumiere;
            }

            float distanceFocaleCible = 2.5 + sin(iTime * 0.8) * 1.0;
            float flouProfondeurDeChamp = smoothstep(0.0, 3.0, abs(derniereDistance - distanceFocaleCible));
            couleurSousEchantillon = mix(couleurSousEchantillon, couleurSousEchantillon * 0.4, flouProfondeurDeChamp * 0.6);

            float absorptionBrouillard = 1.0 - exp(-derniereDistance * 0.45);
            couleurSousEchantillon = mix(couleurSousEchantillon, vec3(0.0005, 0.001, 0.002), absorptionBrouillard);

            couleurAccumulee += couleurSousEchantillon;
        }
    }

    couleurAccumulee *= 0.25;

    couleurAccumulee = couleurAccumulee * 1.8 - 0.5 * dot(couleurAccumulee, vec3(0.299, 0.587, 0.114));

    couleurAccumulee = max(vec3(0.0), couleurAccumulee - 0.025);
    couleurAccumulee = (couleurAccumulee * (2.81 * couleurAccumulee + 0.005)) / (couleurAccumulee * (2.43 * couleurAccumulee + 0.55) + 0.35);

    float decalageChromatique = (0.0015 + 0.002 * sin(iTime * 2.0)) * length(coordNormalisees);
    vec3 couleurFinale;
    couleurFinale.r = couleurAccumulee.r;
    couleurFinale.g = couleurAccumulee.g;
    couleurFinale.b = couleurAccumulee.b * (1.0 + decalageChromatique * 2.5);

    float grain = (fract(sin(dot(coordPixel, vec2(12.9898, 78.233))) * 43758.5453) - 0.5) * 0.005;
    couleurFinale += grain;

    couleurSortie = vec4(pow(clamp(couleurFinale, 0.0, 1.0), vec3(1.0 / 2.2)), 1.0);
}
